const event = $json.body ?? $json;
const message = event.message ?? {};
const action = event.action ?? event.common?.invokedFunction ?? {};
const parameters = Object.fromEntries((action.parameters ?? []).map((p) => [p.key, p.value]));
const threadName = message.thread?.name ?? event.thread?.name ?? `${event.space?.name ?? 'unknown'}:${message.name ?? Date.now()}`;
const text = String(message.argumentText ?? message.text ?? event.text ?? '').trim();
const sourceUrl = message.name ? `https://chat.google.com/room/${encodeURIComponent(event.space?.name ?? '')}/${encodeURIComponent(message.name)}` : null;

return [{
  json: {
    eventType: event.type ?? event.eventType ?? (event.action ? 'CARD_CLICK' : 'MESSAGE'),
    actionName: action.actionMethodName ?? action.function ?? parameters.action ?? null,
    actionToken: parameters.confirmationToken ?? parameters.token ?? null,
    spaceName: event.space?.name ?? null,
    threadName,
    messageName: message.name ?? null,
    sender: {
      displayName: event.user?.displayName ?? message.sender?.displayName ?? null,
      email: event.user?.email ?? message.sender?.email ?? null,
    },
    text,
    source: {
      kind: 'google-chat',
      url: sourceUrl,
      meetingDocId: parameters.meetingDocId ?? null,
    },
  },
}];

const normalized = $('Normalize Chat Event').item.json;
const messages = Array.isArray($json.messages) ? $json.messages.slice(-20) : [];
return [{ json: { ...normalized, threadMessages: messages } }];

const normalized = $('Normalize Chat Event').item.json;
const raw = $json.output ?? $json.text ?? $json.response ?? $json.message?.content ?? '{}';
let decision;
try {
  const text = String(raw).replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  decision = JSON.parse(text);
} catch (error) {
  decision = {
    outcome: 'clarify',
    summary: 'I could not safely parse the research response.',
    questions: ['Please resend the request or ask a human to review the bot configuration.'],
    draft: null,
    evidence: [],
    statePatch: { phase: 'clarifying' },
  };
}

const staticData = $getWorkflowStaticData('global');
staticData.threads = staticData.threads || {};
const threadKey = normalized.threadName;
const prior = staticData.threads[threadKey] || {};
const confirmed = normalized.actionName === 'confirm_create'
  && prior.phase === 'confirming'
  && prior.confirmationToken === normalized.actionToken
  && prior.draft;

if (confirmed) {
  return [{
    json: {
      ...normalized,
      route: 'create',
      issuePayload: {
        repo: 'trimble-oss/modus-wc-2.0',
        title: prior.draft.title,
        summary: prior.draft.summary,
        type: prior.draft.type,
        components: prior.draft.components || [],
        labels: prior.draft.labels || ['needs-scaffolding'],
        source: normalized.source,
        rawConversation: prior.rawConversation || [],
        contextEvidence: prior.draft.evidence || [],
        autoApprove: false,
      },
    },
  }];
}

const nextPhase = decision.outcome === 'clarify' ? 'clarifying'
  : decision.outcome === 'confirm_create' ? 'confirming'
  : decision.outcome === 'stop' ? 'discarded'
  : 'complete';
const nextState = {
  ...prior,
  phase: nextPhase,
  updatedAt: Date.now(),
  questions: decision.questions || [],
  draft: decision.draft || null,
  evidence: decision.evidence || [],
  rawConversation: [...(prior.rawConversation || []), { sender: normalized.sender, text: normalized.text }].slice(-50),
};
if (decision.outcome === 'confirm_create' && decision.draft) {
  nextState.confirmationToken = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}
if (decision.outcome === 'stop') {
  delete staticData.threads[threadKey];
} else {
  staticData.threads[threadKey] = nextState;
}

return [{
  json: {
    ...normalized,
    route: 'reply',
    decision,
    confirmationToken: nextState.confirmationToken || null,
  },
}];

const result = $json;
const issueUrl = result.issueUrl ?? result.url ?? result.issue?.html_url ?? null;
const response = issueUrl
  ? { text: `Draft issue created and sent to Issue Scaffolding: ${issueUrl}` }
  : { text: 'The shared issue service accepted the request but did not return an issue URL. A human should inspect the n8n execution before retrying.' };
return [{ json: { chatResponse: response } }];

const decision = $json.decision || {};
const token = $json.confirmationToken;
const questions = (decision.questions || []).map((q, index) => `${index + 1}. ${q}`).join('<br>');
const evidence = (decision.evidence || []).map((item) => `${item.claim} (<a href=\"${item.source}\">source</a>)`).join('<br>');
const section = {
  widgets: [{ textParagraph: { text: decision.summary || 'I researched the request.' } }],
};
if (questions) section.widgets.push({ textParagraph: { text: questions } });
if (evidence) section.widgets.push({ textParagraph: { text: `<b>Evidence</b><br>${evidence}` } });
if (decision.outcome === 'confirm_create' && decision.draft) {
  section.widgets.push({ textParagraph: { text: `<b>Draft:</b> ${decision.draft.title}<br>${decision.draft.summary || ''}` } });
  section.widgets.push({ buttonList: { buttons: [
    { text: 'Confirm and create', onClick: { action: { actionMethodName: 'confirm_create', parameters: [{ key: 'confirmationToken', value: token }] } } },
    { text: 'Edit / clarify', onClick: { action: { actionMethodName: 'edit_draft' } } },
    { text: 'Discard', onClick: { action: { actionMethodName: 'discard' } } },
  ] } });
}
if (decision.outcome === 'clarify') {
  section.widgets.push({ textParagraph: { text: 'Reply in this thread with your answers. I will research again before drafting.' } });
}
return [{ json: { chatResponse: { cardsV2: [{ cardId: `ticket-${Date.now()}`, card: { header: { title: 'Modus ticket assistant', subtitle: decision.outcome || 'research' }, sections: [section] } }] } } }];
